input.script:
phase("检查");
log("E2E_DWT_LOG 开始跑四条检查命令");
const ok = await world.run("node", ["-e", "console.log('E2E_DWT_OK_1');console.log('E2E_DWT_OK_2');console.log('E2E_DWT_OK_3');console.log('E2E_DWT_OK_4')"]);
const bad = await world.run("node", ["-e", "console.error('Error: E2E_DWT_BAD config missing');process.exit(3)"]);
const long = await world.run("node", ["-e", "for(let i=1;i<=260;i++)console.log('E2E_DWT_LONG_'+i)"]);
const tail = await world.run("node", ["-e", "process.stdout.write('E2E_DWT_HEAD_'.repeat(20)+'E2E_DWT_TAIL_END')"], { output: { tail: 16 } });
log(`E2E_DWT_LOG 检查结束：${ok.exitCode} / ${bad.exitCode}`);
phase("复核");
const verdict = await agent("复核员").ask(`E2E_DWT_TASK 依据两条检查的退出码 ${ok.exitCode} 与 ${bad.exitCode} 给出一句结论。`);
return { ok: ok.exitCode, bad: bad.exitCode, longLines: long.stdout.split("\n").length, tail: tail.stdout, verdict };
